import os

from algo.dps import DPS


class Custom(DPS):
    # DPS (Chung et al., ICLR 2023): InverseBench's implementation, tuned per setting.

    # InverseBench (arXiv:2503.11043) appendix table tab:algo-parameters.
    GUIDANCE = {
        'inv-scatter': 280.0,
        'blackhole-3pct': 0.003,
        'blackhole-10pct': 0.003,
    }

    def __init__(self, net, forward_op, diffusion_scheduler_config=None,
                 guidance_scale=10.0, sde=True, **kwargs):
        guidance_scale = self.GUIDANCE.get(os.environ.get('ENV', ''), guidance_scale)
        diffusion_scheduler_config = diffusion_scheduler_config or {
            'num_steps': 1000, 'schedule': 'vp', 'timestep': 'vp', 'scaling': 'vp'}
        super().__init__(net, forward_op, diffusion_scheduler_config, guidance_scale, sde=sde)

import os

from algo.lgd import LGD


class Custom(LGD):
    # LGD (Song et al., ICML 2023): InverseBench's implementation, tuned per setting.

    # InverseBench (arXiv:2503.11043) appendix table tab:algo-parameters:
    # (guidance scale, number of MC samples).
    SETTINGS = {
        'inv-scatter': (3200.0, 20),
        'blackhole-3pct': (0.0082, 8),
        'blackhole-10pct': (0.0082, 8),
    }

    def __init__(self, net, forward_op, diffusion_scheduler_config=None,
                 guidance_scale=3e-3, num_samples=3, batch_grad=True, sde=True, **kwargs):
        guidance_scale, num_samples = self.SETTINGS.get(
            os.environ.get('ENV', ''), (guidance_scale, num_samples))
        diffusion_scheduler_config = diffusion_scheduler_config or {
            'num_steps': 1000, 'schedule': 'vp', 'timestep': 'vp', 'scaling': 'vp'}
        super().__init__(net, forward_op, diffusion_scheduler_config, guidance_scale,
                         num_samples=num_samples, batch_grad=batch_grad, sde=sde)

import os

from algo.daps import DAPS


class Custom(DAPS):
    # DAPS (Zhang et al., CVPR 2025): InverseBench's implementation, tuned per setting.

    # scattering: InverseBench (arXiv:2503.11043) appendix table tab:algo-parameters, DAPS rows;
    # the final annealing level (not in the table) selected on the validation split.
    SETTINGS = {
        'inv-scatter': {
            'annealing_scheduler_config': {'num_steps': 200, 'sigma_min': 0.01},
            'diffusion_scheduler_config': {'num_steps': 10},
            'lgvd_config': {'lr': 4e-5, 'num_steps': 50, 'tau': 1e-4, 'lr_min_ratio': 1.0},
        },
        # black hole: configs/sweep/blackhole/daps.yaml space, selected on the validation split
        # (psnr); all other values are configs/algorithm/daps.yaml defaults.
        'blackhole': {
            'annealing_scheduler_config': {'sigma_min': 0.0031622776601683794},
            'lgvd_config': {'lr': 1e-08, 'num_steps': 25},
        },
    }
    SETTINGS['blackhole-3pct'] = SETTINGS['blackhole-10pct'] = SETTINGS['blackhole']

    def __init__(self, net, forward_op, annealing_scheduler_config={},
                 diffusion_scheduler_config={}, lgvd_config={}, **kwargs):
        cfg = {
            'annealing_scheduler_config': dict(annealing_scheduler_config),
            'diffusion_scheduler_config': dict(diffusion_scheduler_config),
            'lgvd_config': dict(lgvd_config),
        }
        for group, values in self.SETTINGS.get(os.environ.get('ENV', ''), {}).items():
            cfg[group].update(values)
        super().__init__(net, forward_op, **cfg)

